// A pretend server: fakeFetch("menu.json") answers like fetch would, after 200 ms.
const MENU_JSON = "[{\"id\":1,\"name\":\"Party jollof\",\"price\":3500,\"category\":\"Rice\",\"favourite\":true,\"soldOut\":false},{\"id\":2,\"name\":\"Fried rice\",\"price\":3500,\"category\":\"Rice\",\"favourite\":false,\"soldOut\":true},{\"id\":3,\"name\":\"Egusi + pounded yam\",\"price\":4500,\"category\":\"Soups & swallow\",\"favourite\":true,\"soldOut\":false},{\"id\":4,\"name\":\"Pepper soup\",\"price\":3000,\"category\":\"Soups & swallow\",\"favourite\":true,\"soldOut\":false},{\"id\":5,\"name\":\"Fried plantain\",\"price\":1200,\"category\":\"Sides\",\"favourite\":false,\"soldOut\":false},{\"id\":6,\"name\":\"Zobo (50cl)\",\"price\":700,\"category\":\"Drinks\",\"favourite\":true,\"soldOut\":false}]"
const fakeFetch = (url) => new Promise((resolve) => setTimeout(() => resolve(
  url === "menu.json"
    ? { ok: true, status: 200, json: async () => JSON.parse(MENU_JSON) }
    : { ok: false, status: 404, json: async () => ({}) }), 200))
const naira = (n) => "₦" + n.toLocaleString("en-NG")

// 1. async loadMenu(fetchFn = fetch): fetch "menu.json", throw Error(`HTTP ${status}`) if !ok, return the JSON
// 2. cardHTML(dish): <article class="card"><h3>name</h3><p>naira(price)</p></article>
// 3. async showFavourites(fetchFn = fetch):
//    - .favourites shows "Loading…" first
//    - then only the favourite dishes that aren't sold out, as cards
//    - on any error: <p class="error">Couldn't load today's favourites.</p>
// 4. Call showFavourites(fakeFetch) at the bottom

async function loadMenu(fetchFn = fetch) {
  const response = await fetchFn("menu.json")
  if (!response.ok) throw new Error(`HTTP ${response.status}`)
  return response.json()
}

function cardHTML(dish) {
  return `<article class="card"><h3>${dish.name}</h3><p>${naira(dish.price)}</p></article>`
}

async function showFavourites(fetchFn = fetch) {
  const box = document.querySelector(".favourites")
  box.textContent = "Loading…"
  try {
    const dishes = await loadMenu(fetchFn)
    box.innerHTML = dishes.filter((d) => d.favourite && !d.soldOut).map(cardHTML).join("")
  } catch {
    box.innerHTML = `<p class="error">Couldn't load today's favourites.</p>`
  }
}

showFavourites(fakeFetch)
